<?php require '_layout.php';$db=db();
if($_SERVER['REQUEST_METHOD']==='POST'){$d=$_POST;$id=(int)($d['id']??0);
 if(isset($d['del'])&&$id)$db->prepare('DELETE FROM promo_codes WHERE id=?')->execute([$id]);
 elseif(trim($d['code'])!==''){$v=[strtoupper(preg_replace('/\s+/','',$d['code'])),$d['type']=='fixed'?'fixed':'percent',(float)$d['value'],(float)$d['min_order'],$d['expires']?:null,isset($d['active'])?1:0];
  try{if($id)$db->prepare('UPDATE promo_codes SET code=?,type=?,value=?,min_order=?,expires=?,active=? WHERE id=?')->execute(array_merge($v,[$id]));else $db->prepare('INSERT INTO promo_codes(code,type,value,min_order,expires,active) VALUES(?,?,?,?,?,?)')->execute($v);}catch(Exception $x){}}
 header('Location: promos.php?ok=1');exit;}
ahead('Promo codes','promos.php');?><?=isset($_GET['ok'])?'<p class="okm">Saved</p>':''?><p>Customers type the code at checkout. Percent codes take a % off the basket, fixed codes take £ off. The minimum order is checked before the code applies.</p>
<?php foreach(array_merge($db->query('SELECT * FROM promo_codes ORDER BY id DESC')->fetchAll(),[['id'=>0,'code'=>'','type'=>'percent','value'=>'','min_order'=>'','expires'=>'','active'=>1]]) as $z): ?>
<form method="post" class="zr"><?=csrf()?><input type="hidden" name="id" value="<?=$z['id']?>"><input name="code" placeholder="<?=$z['id']?'':'NEW CODE'?>" value="<?=e($z['code'])?>"><select name="type"><option value="percent">% off</option><option value="fixed" <?=$z['type']=='fixed'?'selected':''?>>£ off</option></select><input name="value" type="number" step="0.01" placeholder="Value" value="<?=e($z['value'])?>"><input name="min_order" type="number" step="0.01" placeholder="Min order £" value="<?=e($z['min_order'])?>"><input name="expires" type="date" value="<?=e($z['expires'])?>"><label><input type="checkbox" name="active" <?=$z['active']?'checked':''?>> Live</label><button class="btn"><?=$z['id']?'Save':'Add code'?></button><?php if($z['id']): ?><button class="btn ghost" name="del" value="1" onclick="return confirm('Delete?')">Delete</button><?php endif; ?></form><?php endforeach; afoot();
